insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-dnsa', 'Add-DnsServerResourceRecordA -ZoneName <zona> -Name <nome> -IPv4Address <ip>', 'Add-DnsServerResourceRecordA -ZoneName corp.datalab.local -Name web -IPv4Address 10.0.1.12', 'Cria um registro A: o nome (web.corp.datalab.local) aponta para o IP.', 'Para os usuários acessarem um servidor pelo nome.', 'win', 95) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-dnscname', 'Add-DnsServerResourceRecordCName -ZoneName <zona> -Name <apelido> -HostNameAlias <nome completo>', 'Add-DnsServerResourceRecordCName -ZoneName corp.datalab.local -Name www -HostNameAlias web.corp.datalab.local', 'Cria um apelido (CNAME) que aponta para outro nome.', 'Para ter um nome amigável (www) sem repetir o IP.', 'win', 96) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
insert into public.command_help (key, cmd, example, what, when_to_use, os, sort) values ('win-resolve', 'Resolve-DnsName <nome>  /  nslookup <nome>', 'Resolve-DnsName www.corp.datalab.local', 'Pergunta ao DNS qual o IP de um nome e mostra o caminho (CNAME → A).', 'Para testar registros DNS.', 'win', 97) on conflict (key) do update set cmd = excluded.cmd, example = excluded.example, what = excluded.what, when_to_use = excluded.when_to_use, os = excluded.os, sort = excluded.sort;
