insert into public.problems (id, n, rank_id, title, summary, handoff, difficulty, xp, credits, skill, roles, bot_minutes, weight, trigger_kind, complete, lesson_id, when_rule, target, setup, vars, devices, bot_action, active, updated_at) values ('sr_ufw_ativar', 5, 'sr', 'Ligar o firewall sem se trancar · {{dev.name}}', 'O {{dev.name}} está sem firewall. Ligue, deixando entrar só o SSH (22) e o site (80). A ordem importa: quem liga antes de liberar a 22 se tranca para fora.', null, 5, 200, 30, 'seguranca', array['seguranca', 'sysadmin']::text[], 15, 1, 'random', 'lesson', null, null, '{"kind":"server","state":"online","os":"linux","healthy":true,"web":true}'::jsonb, '{"linux":"fwoff"}'::jsonb, '{}'::jsonb, '{}'::jsonb, null, true, now()) on conflict (id) do update set n = excluded.n, rank_id = excluded.rank_id, title = excluded.title, summary = excluded.summary, handoff = excluded.handoff, difficulty = excluded.difficulty, xp = excluded.xp, credits = excluded.credits, skill = excluded.skill, roles = excluded.roles, bot_minutes = excluded.bot_minutes, weight = excluded.weight, trigger_kind = excluded.trigger_kind, complete = excluded.complete, lesson_id = excluded.lesson_id, when_rule = excluded.when_rule, target = excluded.target, setup = excluded.setup, vars = excluded.vars, devices = excluded.devices, bot_action = excluded.bot_action, active = true, updated_at = now();
